def bin_search(L, start, end, x):
   if start > end:
       return False
   mid = (start + end) // 2
   if x == L[mid]:
       return True
   elif x > L[mid]:
       start = mid + 1
   else:
       end = mid - 1
   return bin_search(L, start, end, x)

